def multi_list(rows, cols):
    """The program dawnr proved in `t`, written in Python (checked against `t`, not itself proved).

    requires rows >= 0
    requires cols >= 0
    ensures  len(r) == rows
    ensures  forall i in [0, rows) . len(r[i]) == cols
    ensures  forall i in [0, rows) . forall j in [0, cols) . r[i][j] == i * j

    Outside its `requires` it raises ValueError: nothing was proved there.
    """
    if not (_t_ints(rows, 0)):
        raise TypeError('multi_list: `rows` must be an integer; nothing was proved for anything else')
    if not (_t_ints(cols, 0)):
        raise TypeError('multi_list: `cols` must be an integer; nothing was proved for anything else')
    if not _t_requires(rows, cols):
        raise ValueError('multi_list: this input is outside what was proved (requires rows >= 0; cols >= 0)')
    _t_result = _t_core(rows, cols)
    return _t_list(_t_result)

def _t_core(rows, cols):
    r = ()
    i = 0
    # invariant: 0 <= i
    # invariant: i <= rows
    # invariant: len(r) == i
    # invariant: forall k in [0, i) . len(r[k]) == cols
    # invariant: forall k in [0, i) . forall j in [0, cols) . r[k][j] == k * j
    # decreases: rows - i
    while (i < rows):
        row = ()
        j = 0
        # invariant: 0 <= j
        # invariant: j <= cols
        # invariant: len(row) == j
        # invariant: forall k in [0, j) . row[k] == i * k
        # decreases: cols - j
        while (j < cols):
            row = (row + ((i * j), ))
            j = (j + 1)
        r = (r + (row, ))
        i = (i + 1)
    return r

def _t_requires(rows, cols):
    try:
        return bool((rows >= 0)) and bool((cols >= 0))
    except (IndexError, ZeroDivisionError):   # a `requires` with no value here admits nothing
        return False

def _t_ints(v, depth):
    if depth == 0:
        return isinstance(v, int) and not isinstance(v, bool)
    return isinstance(v, (list, tuple)) and all(_t_ints(x, depth - 1) for x in v)

def _t_list(v):
    return [_t_list(x) for x in v] if isinstance(v, tuple) else v

